import { DEFAULT_CARD_SIZE } from "../../card/card";
export const convertCardSizeToState = (card) => {
    const { size = DEFAULT_CARD_SIZE } = card.props;
    switch (size) {
        case "XXL": {
            return {
                lg: 12
            };
        }
        case "XL": {
            return {
                lg: 9
            };
        }
        case "L": {
            return {
                lg: 6
            };
        }
        case "M": {
            return {
                lg: 5
            };
        }
        case "S": {
            return {
                lg: 4
            };
        }
        case "XXS": {
            return {
                lg: 2
            };
        }
        default:
        case "XS": {
            return {
                lg: 3
            };
        }
    }
};
